def transform(grid):
    """Fill between aligned groups of at least three non-background cells."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    changed = True
    while changed:
        changed = False
        for r in range(h):
            occupied = [c for c, value in enumerate(out[r]) if value != background]
            if len(occupied) >= 3:
                for c in range(occupied[0], occupied[-1] + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
                        changed = True
        for c in range(w):
            occupied = [r for r in range(h) if out[r][c] != background]
            if len(occupied) >= 3:
                for r in range(occupied[0], occupied[-1] + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
                        changed = True
    return out
