def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    positions = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            counts[value] = counts.get(value, 0) + 1
            if value != 0:
                positions.append((r, c, value))
    background = max(counts, key=counts.get)
    ink = [[grid[r][c] != background for c in range(w)] for r in range(h)]
    active = [(r, c) for r in range(h) for c in range(w) if ink[r][c]]
    if not active:
        return [row[:] for row in grid]
    min_r = min(r for r, c in active)
    max_r = max(r for r, c in active)
    out = [row[:] for row in grid]

    # Fill gaps along rows containing several marks; the top/bottom boundary
    # can also be a two-endpoint closing edge.
    for r in range(h):
        cols = [c for c in range(w) if ink[r][c]]
        if len(cols) >= 3 or (r in (min_r, max_r) and len(cols) >= 2):
            for c in range(cols[0], cols[-1] + 1):
                if not ink[r][c]:
                    out[r][c] = 2

    # Fill long aligned columns only when the original line has at least
    # three marks, so row fills do not cascade into new column fills.
    for c in range(w):
        rows = [r for r in range(h) if ink[r][c]]
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if not ink[r][c]:
                    out[r][c] = 2
    return out
