def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marked = [[grid[r][c] != background for c in range(w)] for r in range(h)]
    coords = [(r, c) for r in range(h) for c in range(w) if marked[r][c]]
    out = [row[:] for row in grid]
    if not coords:
        return out
    min_r = min(r for r, c in coords)
    max_r = max(r for r, c in coords)
    min_c = min(c for r, c in coords)
    max_c = max(c for r, c in coords)

    # Rows/columns with at least three original marks are extended across the
    # full marked bounding box. The bottom boundary can also close with two.
    for r in range(h):
        n = sum(marked[r][c] for c in range(w))
        if n >= 3 or (r == max_r and n >= 2):
            for c in range(min_c, max_c + 1):
                if not marked[r][c]:
                    out[r][c] = 2
    for c in range(w):
        n = sum(marked[r][c] for r in range(h))
        if n >= 3:
            for r in range(min_r, max_r + 1):
                if not marked[r][c]:
                    out[r][c] = 2
    return out
