                if not marked[r][c]:
                    out[r][c] = 2

    # Complete rows with at least three original marks, using the endpoints
    # after vertical bridging. A two-endpoint bottom edge closes only when
    # the row above was bridged at both endpoints (as in the demonstrated case).
