    active_cols = [c for c in range(w) if any(marked[r][c] for r in range(h))]
    if not active_rows or not active_cols:
        return out
    top, bottom = active_rows[0], active_rows[-1]
    left, right = active_cols[0], active_cols[-1]
    row_counts = [sum(marked[r]) for r in range(h)]

    # Bridge repeated vertical strokes between their outermost marked cells.
    def bridge_vertical(use_output=False):
        for c in range(w):
            rs = [r for r in range(h) if (out[r][c] != background if use_output else marked[r][c])]
            original_rs = [r for r in range(h) if marked[r][c]]
            qualifies = (len(original_rs) >= 4 or
