                if out[r][c] == background:
                    out[r][c] = 2

    # Fill a single interrupted interval in an interior horizontal stroke.
    for r in range(h):
        if r in (top, bottom):
            continue
        original_cols = [c for c in range(w) if marked[r][c]]
        current_cols = [c for c in range(w) if out[r][c] != background]
